// Pagina-opbouw: pas hier de inhoud en indeling aan. Geen robotprotocol.
function stats() {
  return `<div class="summary-grid"><section class="summary eggs-card"><div class="card-label">In het nest ${stamp(data.eggTime)}</div><div class="eggs-content">${eggs()}<button class="icon-button" data-action="edit-eggs" aria-label="Aantal eieren aanpassen" title="Aantal aanpassen">${icon('edit')}</button></div><div class="summary-bottom"><strong>${data.eggs} eieren</strong><button class="text-button" data-action="collect" ${data.eggs===0?'disabled':''}>Verzameld ${icon('arrow')}</button></div></section><section class="summary door-card"><div class="card-label">Hokdeur <span class="freshness" id="door-freshness"></span></div><div class="door-visual"><div class="door-frame"><div class="door-panel"><i></i></div></div><span class="shield-check">${icon('check')}</span></div><div class="summary-bottom"><strong id="door-state">—</strong><span class="subdued">Deursensor</span></div></section><section class="summary robot-summary"><div class="card-label">Bittle X <span class="telemetry" id="battery-status" title="Simulatorgegevens">${icon('wifi')}${icon('battery')}<span id="battery-value">—</span></span></div><div class="robot-mini"><div class="robot-body"><i></i><b></b><span></span></div><div class="robot-leg l1"></div><div class="robot-leg l2"></div><div class="robot-leg l3"></div><div class="robot-leg l4"></div></div><div class="summary-bottom"><strong class="robot-status">${esc(status())}</strong><span class="live-dot"></span></div></section></div>`;
}

function canvasCard(editor = false) {
  return `<section class="terrain-card ${editor?'editor-map':''}"><div class="terrain-top"><div><span class="eyebrow">${editor?'TERREINEDITOR':'TERREIN'}</span><h2>Mijn tuin</h2></div>${editor?'<span class="local-label">Handmatig</span>':`<a href="#terrein" class="map-link">Aanpassen ${icon('arrow')}</a>`}</div><div class="canvas-wrap"><canvas id="terrain-canvas" tabindex="0" aria-label="Tuinplattegrond${editor?', selecteer en sleep objecten of teken een route':''}"></canvas><div class="map-zoom"><button data-action="zoom-out" aria-label="Uitzoomen">−</button><button data-action="zoom-reset" aria-label="Zoom herstellen">${icon('select')}</button><button data-action="zoom-in" aria-label="Inzoomen">+</button></div>${editor?'<div class="tool-hint" id="tool-hint">Selecteer een object om het te bewerken</div>':`<div class="map-control"><span class="moving-dot"></span><span>Bittle X</span><button id="toggle-motion" data-action="toggle" aria-label="Patrouille starten of pauzeren">${icon(robot.moving?'pause':'play')}</button><button data-action="dock" title="Terug naar dock" aria-label="Terug naar dock">${icon('home')}</button></div>`}</div></section>`;
}

function quickActions() {
  return `<section class="quick-card"><div class="section-heading"><h2>Snelle acties</h2><span class="tiny-label">BITTLE</span></div><button data-action="eggs"><span class="action-icon">${icon('egg')}</span><span>Check de eieren<small>Legnest</small></span>${icon('arrow')}</button><button data-action="water"><span class="action-icon water">${icon('water')}</span><span>Check drinkbak<small>Watervoorraad</small></span>${icon('arrow')}</button><button data-action="patrol"><span class="action-icon">${icon('route')}</span><span>Start patrouille<small>${esc(data.routes[0]?.name||'Nog geen route')}</small></span>${icon('arrow')}</button></section>`;
}

function neighborhoodMap() {
  return `<div class="neighborhood-map"><svg viewBox="0 0 600 240" role="img" aria-label="Fictieve buurtkaart met twee voswaarnemingen"><defs><pattern id="lots" width="70" height="55" patternUnits="userSpaceOnUse"><rect x="8" y="8" width="44" height="33" rx="4" fill="#dce3d0" stroke="#ccd6c0"/><rect x="18" y="16" width="17" height="12" rx="1" fill="#c5bda7"/></pattern></defs><rect width="600" height="240" fill="#e8eddf"/><rect width="600" height="240" fill="url(#lots)"/><path d="M-30 230L190 80 370 150 640 30 M180 0l20 260 M0 50l600 140" fill="none" stroke="#fdfcf3" stroke-width="18"/><path d="M470 -10Q380 90 520 250" fill="none" stroke="#b9d0c8" stroke-width="18"/><circle cx="290" cy="125" r="46" fill="#4f79551a"/><circle cx="290" cy="125" r="7" fill="#3f6649" stroke="white" stroke-width="4"/><g fill="#b67946" stroke="#fffdf6" stroke-width="3"><circle cx="130" cy="100" r="14"/><circle cx="410" cy="190" r="14"/></g><g fill="white" font-size="12" text-anchor="middle"><text x="130" y="104">1</text><text x="410" y="194">2</text></g></svg><span>Voorbeeldkaart</span></div>`;
}

function events(limit = 20) {
  return (data.events || []).slice(0, limit).map(e => `<li><span class="event-dot"></span><div><strong>${esc(e.label)}</strong><small>${esc(e.detail||'')}</small></div><time>${new Date(e.time).toLocaleTimeString('nl-BE',{hour:'2-digit',minute:'2-digit'})}</time></li>`).join('') || '<li>Nog geen activiteit</li>';
}

function dashboard() {
  return `${stats()}<div class="overview-main">${canvasCard()}<div class="overview-side">${quickActions()}<section class="local-camera"><div class="camera-heading"><span>${icon('camera')} Testbeeld</span><small>Simulatie</small></div><img class="camera-frame" alt="Gegenereerd testbeeld, geen echte camera" src="/api/camera/frame"><p class="camera-unavailable" hidden>Beeld niet beschikbaar</p></section></div></div><div class="overview-bottom"><section class="panel neighborhood-preview"><div class="section-heading"><h2>In de buurt <span class="count-badge">2</span></h2><a href="#buurt" class="text-button">Bekijken ${icon('arrow')}</a></div>${neighborhoodMap()}<div class="neighborhood-note"><span class="fox-dot"></span> Vos gespot <span>800 m · 1 u</span></div></section><section class="panel"><div class="section-heading"><h2>Activiteit</h2><a href="#activiteit" class="text-button">Alles ${icon('arrow')}</a></div><ol class="event-list">${events(3)}</ol></section></div>`;
}

function editor() {
  return `<div class="editor-toolbar"><div class="tool-group"><button class="button selected" data-tool="select">${icon('select')} Selecteren</button><button class="button" data-tool="route">${icon('route')} Route tekenen</button><button class="button" data-tool="zone">${icon('zone')} Verboden zone</button></div><div class="tool-group"><button class="icon-button" data-action="undo" title="Ongedaan maken" aria-label="Ongedaan maken">${icon('undo')}</button><button class="icon-button" data-action="redo" title="Opnieuw" aria-label="Opnieuw">${icon('redo')}</button><button class="icon-button" data-action="export" title="Kaart exporteren" aria-label="Kaart exporteren">${icon('download')}</button><button class="icon-button" data-action="import" title="Kaart importeren" aria-label="Kaart importeren">${icon('upload')}</button></div></div><div class="builder-layout"><div>${canvasCard(true)}<div class="drawing-controls" id="drawing-controls" hidden><span id="point-count">0 punten</span><label><input id="route-closed" type="checkbox" checked> Gesloten ronde</label><button class="button" data-action="remove-point">Laatste punt weg</button><button class="button primary" data-action="finish-drawing">Opslaan</button><button class="text-button" data-action="cancel-drawing">Annuleren</button></div><div class="object-library"><div class="section-heading"><h3>Toevoegen</h3><span>Kies, plaats, versleep</span></div><div class="library-grid">${Object.entries(C.TYPES).map(([key,v])=>`<button data-tool="${key}"><span class="library-art ${key}">${icon({coop:'home',nest:'egg',water:'water',plant:'leaf',door:'door',fence:'fence',dock:'battery'}[key])}</span>${v.name}</button>`).join('')}</div></div></div><aside class="inspector"><div id="inspector-content"></div><div class="object-list-heading">ONDERDELEN <span>${data.objects.length}</span></div><div id="object-list"></div></aside></div>`;
}

function missions() {
  return `<div class="page-intro"><p>Routes en controles voor je tuin.</p><a href="#terrein" class="button primary">${icon('plus')} Route tekenen</a></div><div class="mission-layout"><div class="route-cards">${data.routes.map((r,i)=>`<section class="route-card"><div class="route-art"><svg viewBox="0 0 300 130"><path d="M20 100Q30 10 100 35T270 30" fill="none" stroke="#bdcba7" stroke-width="34" stroke-linecap="round"/><polyline points="${r.points.map(p=>`${p.x*.28},${p.y*.2}`).join(' ')}" fill="none" stroke="#456541" stroke-width="2" stroke-dasharray="5 4"/></svg><span>0${i+1}</span></div><div class="route-info"><h2>${esc(r.name)}</h2><small>${r.points.length} punten · ${r.closed?'Gesloten ronde':'Enkele route'}</small><button class="button primary" data-route-start="${esc(r.id)}">${icon('play')} Starten</button></div></section>`).join('')||'<div class="panel">Teken je eerste route in Mijn kippenhok.</div>'}</div>${quickActions()}</div><section class="panel mission-state"><span class="live-dot"></span><strong class="robot-status">${esc(status())}</strong><button class="button" data-action="toggle">${icon('pause')} Pauzeren / hervatten</button><button class="button" data-action="dock">${icon('home')} Naar dock</button></section>`;
}

function buurt() {
  return `<div class="page-intro"><p>Waarnemingen rond je tuin.</p><span class="connection-pill">Buurtbron niet gekoppeld</span></div><section class="panel buurt-full">${neighborhoodMap()}<div class="sighting-row"><span class="sighting-number">1</span><div><h3>Vos bij de veldweg</h3><small>Voorbeeldmelding · onbevestigd</small></div><span>800 m</span><span>${icon('clock')} 1 u</span></div><div class="sighting-row"><span class="sighting-number">2</span><div><h3>Vos aan de bosrand</h3><small>Voorbeeldmelding · onbevestigd</small></div><span>1,4 km</span><span>${icon('clock')} 8 u</span></div></section>`;
}

function technical() {
  return `<div class="page-intro"><p>Test je interface zonder robot. Alle waarden komen uit de lokale simulator.</p><span class="connection-pill">Mockadapter</span></div><div class="technical-grid"><section class="panel"><div class="section-heading"><h2>Testscenario’s</h2><span class="tiny-label">ALLEEN SIMULATIE</span></div><div class="scenario-grid">${[['normal','Normaal'],['offline','Verbinding weg'],['low-battery','Batterij laag'],['door-open','Hokdeur open'],['fox','Vosmelding'],['camera-off','Camera uit']].map(([key,name])=>`<button class="button" data-scenario="${key}">${name}</button>`).join('')}</div><div class="technical-status"><strong class="robot-status">${esc(status())}</strong><span id="tech-source">Bron: mock</span></div><p class="muted">Herstellen met Normaal. Beweging hervat nooit vanzelf.</p></section><section class="panel"><div class="section-heading"><h2>Camera-aansluiting</h2><span class="tiny-label">TESTBEELD</span></div><img class="camera-frame" src="/api/camera/frame" alt="Lokaal gegenereerd testbeeld"><p class="camera-unavailable" hidden>Beeld niet beschikbaar</p></section><section class="panel"><div class="section-heading"><h2>Opdrachten</h2><span class="tiny-label">BEVESTIGINGEN</span></div><div id="command-list"></div></section><section class="panel"><div class="section-heading"><h2>Motoren & sensoren</h2><span class="connection-pill">Niet gekoppeld</span></div><p class="muted">Er zijn nog geen servo- of motormetingen. De connector kan die later aanleveren, zonder het hoofddashboard te veranderen.</p><div class="connector-list"><div>Bittle / BiBoard V1 <small>Transport nog te bepalen</small></div><div>Camera / extra ESP32 <small>Aparte connector mogelijk</small></div><div>PyBullet / Bittle Studio <small>Simulatieadapter nog niet gekoppeld</small></div></div><details><summary>Ontvangen gegevens</summary><pre id="raw-telemetry"></pre></details></section></div>`;
}
